// GENERATED by scripts/bundle-function.mjs from email.ts + index.ts. Do not edit by hand.
// Paste ALL of this into the Supabase dashboard function editor.

// Pure helpers for the registration email (no network, easy to test).

type Rsvp = {
  id: string;
  ticket_code: string;
  name: string;
  email: string;
  phone: string;
  attending: string;
  bringing: string | null;
  consent_at: string;
  policy_version: string;
  created_at: string;
  ticket_token?: string; // present in the webhook payload; NEVER put in an email
};

function escapeHtml(v: unknown): string {
  return String(v ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// One line, no control characters (prevents header tricks), max 80 chars.
function oneLine(v: unknown, max = 80): string {
  const s = String(v ?? '').replace(/[\u0000-\u001f\u007f]+/g, ' ').replace(/\s+/g, ' ').trim();
  return s.length > max ? s.slice(0, max - 1) + '…' : s;
}

function lagosTime(iso: string): string {
  const d = new Date(iso);
  if (isNaN(d.getTime())) return '';
  return new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Africa/Lagos', weekday: 'short', day: 'numeric', month: 'short', year: 'numeric',
    hour: 'numeric', minute: '2-digit', hour12: true
  }).format(d) + ' (WAT)';
}

function isValidRecord(r: unknown): r is Rsvp {
  if (!r || typeof r !== 'object') return false;
  const x = r as Record<string, unknown>;
  return typeof x.id === 'string' && typeof x.ticket_code === 'string' && typeof x.name === 'string' &&
    typeof x.email === 'string' && typeof x.phone === 'string' && (x.attending === 'yes' || x.attending === 'no') &&
    typeof x.created_at === 'string';
}

function buildEmail(r: Rsvp): { subject: string; html: string; text: string } {
  const coming = r.attending === 'yes' ? 'Yes' : 'No';
  const subject = `Miva Fest RSVP: ${oneLine(r.name)} (${coming}) - ${oneLine(r.ticket_code, 20)}`;
  const rows: [string, string][] = [
    ['Ticket code', r.ticket_code],
    ['Full name', r.name],
    ['Email address', r.email],
    ['Phone number', r.phone],
    ['Coming', coming],
    ['Bringing', r.bringing || '-'],
    ['Payment', r.attending === 'yes' ? 'Not paid yet (mark Paid in the admin site)' : 'No ticket'],
    ['Consent given', lagosTime(r.consent_at) + ' - policy ' + (r.policy_version || '')]
  ];
  const cell = 'padding:10px 12px;border:1px solid #c9c2b2;font-family:Arial,sans-serif;font-size:15px;vertical-align:top';
  const html =
    `<div style="font-family:Arial,sans-serif;color:#0B1530;max-width:640px">` +
    `<p style="font-size:16px">Someone just registered for <b>Miva Fest</b>.</p>` +
    `<table role="presentation" style="border-collapse:collapse;width:100%">` +
    `<tr><th style="${cell};background:#1237A8;color:#fff;text-align:left">Field</th>` +
    `<th style="${cell};background:#1237A8;color:#fff;text-align:left">Answer</th></tr>` +
    rows.map(([k, v]) => `<tr><td style="${cell};font-weight:bold;width:38%">${escapeHtml(k)}</td>` +
      `<td style="${cell};font-family:Consolas,monospace">${escapeHtml(v)}</td></tr>`).join('') +
    `</table>` +
    `<p style="font-size:15px;text-align:center;margin-top:18px"><b>Submitted at ${escapeHtml(lagosTime(r.created_at))}</b></p>` +
    `<p style="font-size:13px;color:#555">You get this because you switched on registration emails in the Miva Fest admin site.</p>` +
    `</div>`;
  const text = `Someone just registered for Miva Fest.\n\n` +
    rows.map(([k, v]) => `${k}: ${oneLine(v, 300)}`).join('\n') +
    `\n\nSubmitted at ${lagosTime(r.created_at)}\n`;
  return { subject, html, text };
}

// Constant-time string compare for the webhook secret.
function safeEqual(a: string, b: string): boolean {
  if (typeof a !== 'string' || typeof b !== 'string' || a.length !== b.length || a.length === 0) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

// Supabase Edge Function: email admins about each new registration.
//
// Triggered by a Database Webhook (table public.rsvps, event INSERT) that
// sends the header  x-webhook-secret: <WEBHOOK_SECRET>.
//
// Secrets (Supabase > Edge Functions > Secrets), never in git:
//   RESEND_API_KEY   from resend.com
//   WEBHOOK_SECRET   any long random string; the same value goes in the webhook header
//   MAIL_FROM        optional, e.g. "Miva Fest <rsvp@your-domain>" once a domain is verified
// Provided automatically by Supabase: SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY
//
// Who gets the email: every row in public.admins with receives_emails = true
// (the super admin switches this on/off in the admin site).

const TIMEOUT_MS = 10000;

function env(name: string): string {
  const v = Deno.env.get(name);
  if (!v) throw new Error(`missing secret ${name}`);
  return v;
}

async function call(url: string, init: RequestInit): Promise<Response> {
  const c = new AbortController();
  const t = setTimeout(() => c.abort(), TIMEOUT_MS);
  try { return await fetch(url, { ...init, signal: c.signal }); } finally { clearTimeout(t); }
}

function dbHeaders(): Record<string, string> {
  const key = env('SUPABASE_SERVICE_ROLE_KEY');
  const h: Record<string, string> = { apikey: key, 'Content-Type': 'application/json' };
  if (key.split('.').length === 3) h.Authorization = `Bearer ${key}`;
  return h;
}

const reply = (status: number, body: Record<string, unknown>) =>
  new Response(JSON.stringify(body), { status, headers: { 'Content-Type': 'application/json' } });

Deno.serve(async (req) => {
  if (req.method !== 'POST') return reply(405, { error: 'method' });
  if (!safeEqual(req.headers.get('x-webhook-secret') ?? '', env('WEBHOOK_SECRET'))) {
    return reply(401, { error: 'unauthorized' });
  }

  let payload: { type?: string; table?: string; schema?: string; record?: unknown };
  try { payload = await req.json(); } catch { return reply(400, { error: 'bad json' }); }
  if (payload.type !== 'INSERT' || payload.table !== 'rsvps' || payload.schema !== 'public') {
    return reply(200, { skipped: true });
  }
  const r = payload.record;
  if (!isValidRecord(r)) return reply(400, { error: 'bad record' });

  const base = env('SUPABASE_URL');
  try {
    const res = await call(`${base}/rest/v1/admins?select=email&receives_emails=eq.true`, { headers: dbHeaders() });
    if (!res.ok) throw new Error(`admins lookup ${res.status}`);
    const to = ((await res.json()) as { email: string }[]).map((a) => a.email);
    if (to.length === 0) return reply(200, { sent: 0, reason: 'no recipients' });

    const { subject, html, text } = buildEmail(r);
    const mail = await call('https://api.resend.com/emails', {
      method: 'POST',
      headers: { Authorization: `Bearer ${env('RESEND_API_KEY')}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        from: Deno.env.get('MAIL_FROM') || 'Miva Fest <onboarding@resend.dev>',
        to, subject, html, text
      })
    });
    if (!mail.ok) throw new Error(`resend ${mail.status}`);

    const mark = await call(`${base}/rest/v1/rsvps?id=eq.${encodeURIComponent(r.id)}`, {
      method: 'PATCH',
      headers: { ...dbHeaders(), Prefer: 'return=minimal' },
      body: JSON.stringify({ notified: true })
    });
    if (!mark.ok) throw new Error(`mark notified ${mark.status}`);

    return reply(200, { sent: to.length });
  } catch (e) {
    // Log only the reason, never the person's details.
    console.error('notify-rsvp failed:', e instanceof Error ? e.message : 'unknown', 'ticket', r.ticket_code);
    return reply(500, { error: 'notify failed' });
  }
});
